            'sections' => [
                ['id' => 'modalites', 'title' => 'Rückgabebedingungen im Überblick', 'paragraphs' => ['Diese Regeln betreffen Fernabsatzkäufe von Verbrauchern, vorbehaltlich gesetzlicher Ausnahmen für bestimmte Waren. Die Rücksendeadresse ist bestätigt; der kostenlose Transport ist mit HOMYA zu organisieren.'], 'items' => ['Widerruf: Mitteilung innerhalb von 14 Kalendertagen nach Empfang; Rücksendung innerhalb von 14 Tagen nach Mitteilung.', 'Erstattung: spätestens 14 Tage nach Mitteilung, vorbehaltlich des unten erläuterten gesetzlichen Zurückbehaltungsrechts. Bankgutschriften hängen vom Anbieter ab.', 'Kostenlose Lieferung nach Frankreich, Belgien und Deutschland; HOMYA trägt Rücksendekosten bei Mitteilung innerhalb von 14 Tagen nach Empfang.', 'Erklärung und Rücksendung: an HOMYA unter der unten veröffentlichten Rücksendeadresse. Eine eindeutige Erklärung genügt für den Widerruf.', 'Mängel unterliegen gesetzlichen Gewährleistungsrechten, getrennt vom Sinneswandel. Kein pauschaler Ausschluss reduzierter, geöffneter oder sperriger Waren.']],
                ['id' => 'delai', 'title' => '14 Tage für die Widerrufserklärung', 'paragraphs' => ['Für Waren mit gesetzlichem Widerrufsrecht haben Sie 14 Kalendertage ab Erhalt durch Sie oder einen benannten Dritten, der nicht der Beförderer ist. Bei mehreren getrennt gelieferten Waren oder einer Ware in mehreren Teillieferungen beginnt die Frist mit dem Erhalt der letzten Ware oder Teillieferung. Der Empfangstag wird nicht mitgezählt. In Frankreich wird ein Fristende an einem Samstag, Sonntag, Feiertag oder arbeitsfreien Tag auf den nächsten Werktag verschoben.', 'Eine Begründung ist nicht nötig. Senden Sie eine eindeutige Erklärung an HOMYA am Sitz laut Impressum. Die E-Mail-Adresse steht auf der Kontaktseite. Ein Sonderangebot beseitigt dieses Recht nicht.']],
                ['id' => 'retour', 'title' => 'Rücksendung und Erstattung', 'paragraphs' => ['Senden Sie Waren unverzüglich und spätestens innerhalb von 14 Tagen nach Widerruf zurück, sofern HOMYA nicht die Abholung anbietet. Die unten angegebene Adresse nimmt auch Paletten, Möbel und sperrige Geräte an.', 'Die Erstattung umfasst Zahlungen für die Ware und gegebenenfalls Standardlieferkosten. Ein Aufpreis für eine vom Kunden gewählte teurere Versandart wird nach dieser Regel nicht erstattet.', 'Die Erstattung erfolgt spätestens 14 Tage ab Mitteilung Ihrer Entscheidung. Soweit gesetzlich zulässig, kann HOMYA bis zum Wareneingang oder zum Versandnachweis warten, je nachdem, welches Ereignis früher eintritt. Dies gilt nicht, wenn HOMYA die Abholung anbietet.', 'Die Erstattung erfolgt über dasselbe Zahlungsmittel, außer Sie stimmen ausdrücklich einer anderen kostenfreien Methode zu. Die Gutschriftfrist des Zahlungsanbieters ist gesondert anzugeben und ersetzt nicht die gesetzliche Frist.', 'HOMYA trägt Rücksendekosten bei Widerruf innerhalb von 14 Tagen nach Empfang. Kostenlose Rücksendungen sind HOMYAs geschäftliche Zusage. Vereinbaren Sie den Transport mit HOMYA: ein vorausbezahltes Etikett für geeignete Pakete oder Abholung sperriger Güter, je nach organisierter Lösung. Falls Sie direkte Rücksendekosten vorstrecken, bewahren Sie Belege für die Erstattung auf; eine vorherige Genehmigung ist keine Voraussetzung des Widerrufsrechts.'], 'return_details' => true],
                ['id' => 'emballage', 'title' => 'Paket oder Abholung vorbereiten', 'paragraphs' => ['Schützen Sie die Ware für den Transport und legen Sie Zubehör sowie die Bestellreferenz bei, falls verfügbar. Originalverpackung wird empfohlen, sofern vorhanden; ihr Fehlen oder das Öffnen eines Pakets beseitigt das Widerrufsrecht nicht automatisch.', 'Ein möglicher Wertverlust muss auf Umgang zurückgehen, der zur Prüfung von Beschaffenheit, Eigenschaften und Funktionsweise nicht notwendig war, unter den gesetzlichen Informationsvoraussetzungen. Es gibt keine pauschale Wiedereinlagerungsgebühr oder Rückgabestrafe.']],
                ['id' => 'exceptions', 'title' => 'Ausnahmen und mangelhafte Waren', 'paragraphs' => ['Gesetzliche Ausnahmen müssen je Produkt geprüft und gegebenenfalls vor dem Kauf mitgeteilt werden, etwa bei tatsächlich nach Kundenspezifikation gefertigten Waren. Ein pauschaler Ausschluss geöffneter, reduzierter oder sperriger Produkte wird hier nicht vorgenommen.', 'Bei Mängeln oder fehlender Konformität geben Sie Ihre Bestellung und das Problem an. Dieser gesetzliche Gewährleistungsanspruch ist nicht auf die 14-tägige Widerrufsfrist begrenzt. Abhilfe im Rahmen der gesetzlichen Konformitätsgarantie ist für Verbraucher kostenfrei, einschließlich notwendiger Transportkosten; dieser Ablauf ist vom Rücktritt wegen Meinungsänderung getrennt.']],
                ['id' => 'france', 'title' => 'Frankreich · Online-Widerruf', 'paragraphs' => ['Artikel L221-21 des Verbrauchergesetzbuchs sieht seit dem 19. Juni 2026 eine kostenlose Widerrufsfunktion für Fernabsatzverträge über eine Online-Oberfläche vor. Sie muss während der Widerrufsfrist verfügbar sein und eine Eingangsbestätigung ermöglichen.']],
                ['id' => 'belgique', 'title' => 'Belgien · Online-Widerruf', 'paragraphs' => ['Laut FÖD Wirtschaft ist eine Online-Widerrufsfunktion seit dem 14. August 2026 vorgeschrieben. Sie muss leicht auffindbar und nutzbar sein, während der Frist zur Verfügung stehen und eine Bestätigung auslösen.']],
                ['id' => 'allemagne', 'title' => 'Deutschland · Widerruf', 'paragraphs' => ['BGB § 356a sieht während der Frist eine zugängliche Widerrufsfunktion, einen ausdrücklichen Bestätigungsschritt und eine aufbewahrbare Eingangsbestätigung mit Erklärung, Datum und Uhrzeit vor. Widerrufsbelehrung und Musterformular müssen an den Verkäufer angepasst werden.']],
                ['id' => 'procedure', 'title' => 'So erklären Sie einen Widerruf', 'paragraphs' => ['Erklären Sie zuerst den Widerruf und organisieren Sie danach den kostenlosen Transport. Die Rücksendeadresse steht oben. Elektronische Kontaktdaten stehen auf der Kontaktseite; eine Erklärung ist auch postalisch möglich.'], 'items' => ['Für einen postalischen Widerruf senden Sie eine eindeutige Erklärung an HOMYA am Sitz laut Impressum. Das Beispiel unten ist freiwillig.', 'Geben Sie die Ware und transportrelevante Zugangsbedingungen an. HOMYA muss einen geeigneten Pakettransport oder die Abholung sperriger Güter organisieren und bezahlen. Zeiten und Abholtermine sind noch zu vereinbaren; das Warten auf Logistikanweisungen darf Ihre Rechte nicht entziehen.', 'Senden Sie fristgerecht zurück und bewahren Sie den Versandnachweis auf. Widerruf erfordert keine vorherige Genehmigung des Verkäufers.', 'Erstattungen folgen den obigen Regeln. Geben Sie die Bestellreferenz an; senden Sie keine Passwörter oder vollständigen Kartendaten.']],
                ['id' => 'declaration', 'title' => 'Beispiel für einen postalischen Widerruf', 'paragraphs' => ['An HOMYA am Sitz laut Impressum. Hiermit widerrufe ich den Vertrag über folgende Ware: [Produkt / Referenz]. Bestellt am [Datum], erhalten am [Datum]. Bestellreferenz: [Referenz]. Name und Anschrift des Verbrauchers: [Name / Adresse]. Datum: [Datum]. Unterschrift bei einer Erklärung auf Papier.', 'Die oben angegebene Adresse empfängt sowohl Ihre Erklärung als auch Rücksendungen. Vereinbaren Sie den Transport sperriger Güter mit HOMYA; die Widerrufserklärung benötigt keine vorherige Zustimmung des Verkäufers.']],
                ['id' => 'preparation', 'title' => 'Noch zu ergänzende HOMYA-Verfahren', 'items' => ['Transporteur, vorausbezahlte Etiketten, kostenlose Abholverfahren und Termine sind noch zu organisieren, insbesondere für sperrige Güter.', 'Online-Widerruf mit Empfangsbestätigung.', 'Wirksame Erstattungsabläufe vor kommerzieller Veröffentlichung prüfen.'], 'paragraphs' => ['Online-Widerruf und Empfangsbestätigung sind noch einzurichten. Post an den Sitz kann die Entscheidung mitteilen; diese Seite übermittelt keine Anfrage.']],
